namespace KasaSika.Domain.Identity;

/// <summary>
/// A phone (or browser) the user has signed in from. The installation id is generated by the app on first
/// launch; it identifies an install, not a person, and is never treated as proof of identity on its own.
/// </summary>
public sealed class Device
{
    private Device() { }

    public Guid Id { get; private set; }
    public Guid UserId { get; private set; }
    public string InstallationId { get; private set; } = "";
    public string Platform { get; private set; } = "";
    public string? Label { get; private set; }
    public DateTimeOffset CreatedAt { get; private set; }
    public DateTimeOffset LastSeenAt { get; private set; }
    public DateTimeOffset? RevokedAt { get; private set; }

    public static Device Register(Guid userId, string installationId, string platform, string? label, DateTimeOffset now) => new()
    {
        Id = Guid.NewGuid(),
        UserId = userId,
        InstallationId = installationId,
        Platform = platform is { Length: > 20 } ? platform[..20] : platform,
        Label = label is { Length: > 100 } ? label[..100] : label,
        CreatedAt = now,
        LastSeenAt = now,
    };

    public void Seen(DateTimeOffset now) => LastSeenAt = now;

    public void Revoke(DateTimeOffset now) => RevokedAt ??= now;
}

public enum DeviceCredentialKind
{
    /// <summary>
    /// A random 256-bit key generated on the phone and kept in the OS keystore behind biometrics. Proves
    /// "this enrolled phone, unlocked by its owner's fingerprint/face". (Prototype: a shared secret. Production
    /// should use a non-exportable asymmetric key / passkey so the server holds only a public key.)
    /// </summary>
    BiometricDeviceKey,
}

public sealed class DeviceCredential
{
    private DeviceCredential() { }

    public Guid Id { get; private set; }
    public Guid UserId { get; private set; }
    public Guid DeviceId { get; private set; }
    public DeviceCredentialKind Kind { get; private set; }
    /// <summary>The device key, encrypted at rest with the server's field-encryption key.</summary>
    public string SecretProtected { get; private set; } = "";
    public DateTimeOffset CreatedAt { get; private set; }
    public DateTimeOffset? RevokedAt { get; private set; }

    public static DeviceCredential Enroll(Guid userId, Guid deviceId, DeviceCredentialKind kind, string secretProtected, DateTimeOffset now) => new()
    {
        Id = Guid.NewGuid(),
        UserId = userId,
        DeviceId = deviceId,
        Kind = kind,
        SecretProtected = secretProtected,
        CreatedAt = now,
    };

    public bool IsActive => RevokedAt is null;

    public void Revoke(DateTimeOffset now) => RevokedAt ??= now;
}
